<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{api}from'../api';const email=ref(''),password=ref(''),error=ref(''),loading=ref(false),router=useRouter();async function login(){loading.value=true;error.value='';try{const{data}=await api.post('/auth/login',{email:email.value,password:password.value});localStorage.setItem('rjay_admin_token',data.token);router.push('/admin')}catch(e:any){error.value=e.response?.data?.message||'Login failed'}finally{loading.value=false}}</script><template><div class="min-vh-100 d-flex align-items-center justify-content-center p-3"><div class="card p-4" style="max-width:420px;width:100%"><div class="brand fs-3">RJAY Hotspot</div><p class="text-secondary">Administrator access</p><div v-if="error" class="alert alert-danger py-2">{{error}}</div><form @submit.prevent="login"><label class="form-label">Email</label><input v-model="email" class="form-control mb-3" type="email" required><label class="form-label">Password</label><input v-model="password" class="form-control mb-4" type="password" required><button class="btn btn-primary w-100" :disabled="loading">{{loading?'Signing in...':'Sign in'}}</button></form></div></div></template>